import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 18 章 如何进行多 Agent 系统设计","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md"}'),p={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md"};function i(l,a,o,d,c,r){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="第-18-章-如何进行多-agent-系统设计" tabindex="-1">第 18 章 如何进行多 Agent 系统设计 <a class="header-anchor" href="#第-18-章-如何进行多-agent-系统设计" aria-label="Permalink to &quot;第 18 章 如何进行多 Agent 系统设计&quot;">​</a></h1><h2 id="_18-1-从-一个-agent-到-一个系统" tabindex="-1">18.1 从&quot;一个 Agent&quot;到&quot;一个系统&quot; <a class="header-anchor" href="#_18-1-从-一个-agent-到-一个系统" aria-label="Permalink to &quot;18.1 从&quot;一个 Agent&quot;到&quot;一个系统&quot;&quot;">​</a></h2><p>第 8 章、第 16 章讲了怎么用团队。这一章讲<strong>设计</strong>：当你要解决一个复杂问题，怎么设计出一套多 Agent 协作的系统，而不是随手拉几个人。</p><h2 id="_18-2-设计的第一原则-能不拆就不拆" tabindex="-1">18.2 设计的第一原则：能不拆就不拆 <a class="header-anchor" href="#_18-2-设计的第一原则-能不拆就不拆" aria-label="Permalink to &quot;18.2 设计的第一原则：能不拆就不拆&quot;">​</a></h2><p>多 Agent 系统有成本：沟通开销、上下文割裂、结果不一致。所以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单 Agent 能解决的 → 绝不拆</span></span>
<span class="line"><span>任务可串行完成 → 不必并行</span></span>
<span class="line"><span>只有拆分收益 &gt; 协作成本 → 才拆</span></span></code></pre></div><p><strong>多 Agent 是手段，不是目的。</strong></p><h2 id="_18-3-什么样的任务值得多-agent" tabindex="-1">18.3 什么样的任务值得多 Agent <a class="header-anchor" href="#_18-3-什么样的任务值得多-agent" aria-label="Permalink to &quot;18.3 什么样的任务值得多 Agent&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>√ 多个专业角色（设计、开发、测试）</span></span>
<span class="line"><span>√ 可并行（各部分互不依赖）</span></span>
<span class="line"><span>√ 单个 Agent 上下文装不下</span></span>
<span class="line"><span>√ 需要交叉验证（写的人不能同时验）</span></span>
<span class="line"><span>× 需求未定、探索阶段</span></span>
<span class="line"><span>× 任务小到一句话能说清</span></span></code></pre></div><h2 id="_18-4-设计一个多-agent-系统的五步法" tabindex="-1">18.4 设计一个多 Agent 系统的五步法 <a class="header-anchor" href="#_18-4-设计一个多-agent-系统的五步法" aria-label="Permalink to &quot;18.4 设计一个多 Agent 系统的五步法&quot;">​</a></h2><p><strong>第 1 步：定义目标与产出</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：上线一个新功能</span></span>
<span class="line"><span>产出：代码 + 测试 + 文档 + 上线检查单</span></span></code></pre></div><p><strong>第 2 步：识别角色</strong></p><p>按任务自然边界切：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划（拆任务）→ 开发（写代码）→ 测试（验证）→ 文档（沉淀）→ 评审（把关）</span></span></code></pre></div><p><strong>第 3 步：定义每个角色的输入输出</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发：输入=需求文档；输出=代码 + 自测说明</span></span>
<span class="line"><span>测试：输入=代码 + 需求；输出=测试报告（通过/问题清单）</span></span></code></pre></div><p><strong>第 4 步：设计协作关系</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划 → 开发 → 测试 → 评审</span></span>
<span class="line"><span>         ↘ 文档 ↙</span></span></code></pre></div><p>明确：谁给谁交付、谁验证谁、谁有最终决定权。</p><p><strong>第 5 步：设定检查点与回退</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查点：开发完成 → 测试验收 → 评审通过 → 交付</span></span>
<span class="line"><span>回退：测试发现问题 → 打回开发，附问题清单</span></span></code></pre></div><h2 id="_18-5-多-agent-系统的黄金结构" tabindex="-1">18.5 多 Agent 系统的黄金结构 <a class="header-anchor" href="#_18-5-多-agent-系统的黄金结构" aria-label="Permalink to &quot;18.5 多 Agent 系统的黄金结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         Leader（我：拆解、协调、验收）</span></span>
<span class="line"><span>        /     |      \\      \\</span></span>
<span class="line"><span>   规划   开发    测试    文档</span></span>
<span class="line"><span>     \\      \\      /      /</span></span>
<span class="line"><span>        交叉验证 → 汇总交付</span></span></code></pre></div><p><strong>核心规则：写的人不验，验的人不写。</strong> 这是质量的第一道保险。</p><h2 id="_18-6-常见设计错误" tabindex="-1">18.6 常见设计错误 <a class="header-anchor" href="#_18-6-常见设计错误" aria-label="Permalink to &quot;18.6 常见设计错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>后果</th><th>修正</th></tr></thead><tbody><tr><td>角色过细</td><td>沟通成本爆炸</td><td>合并到 3～5 个角色</td></tr><tr><td>没有 Leader 验收</td><td>各做各的，没人对整体负责</td><td>明确唯一负责人</td></tr><tr><td>任务边界重叠</td><td>重复劳动</td><td>每个子任务唯一归属</td></tr><tr><td>全程并行</td><td>依赖没处理好</td><td>先画依赖图再排期</td></tr></tbody></table><h2 id="_18-7-练习" tabindex="-1">18.7 练习 <a class="header-anchor" href="#_18-7-练习" aria-label="Permalink to &quot;18.7 练习&quot;">​</a></h2><ol><li>选一个你熟悉的复杂任务，按五步法画出系统设计；</li><li>画出角色关系图，标出依赖和检查点；</li><li>用真实任务跑一轮，复盘：拆分是否合理？哪里协作成本最高？</li></ol><blockquote><p>小结：多 Agent 系统设计，本质是<strong>组织结构设计</strong>。拆得好，是团队；拆得差，是团伙。</p></blockquote>`,30)])])}const u=s(p,[["render",i]]);export{g as __pageData,u as default};
